    })
}

pub(super) fn line_cost(u: &Usage, model: &str) -> Option<f64> {
    let (pin, pout, pcw, pcr) = model_price(model)?;
    Some((u.input as f64 * pin
        + u.output as f64 * pout
        + u.cache_creation as f64 * pcw
        + u.cache_read as f64 * pcr)
        / 1_000_000.0)
}

